def gate(stats, max_error_pct, max_p95_ms):
    total = stats.get('Total')
    if not total or not total.get('sampleCount'):
        return (False, ['no data'])
    reasons = []
    if total.get('errorPct', 100) > max_error_pct:
        reasons.append('error rate')
    if total.get('pct2ResTime', float('inf')) > max_p95_ms:
        reasons.append('p95')
    return (not reasons, reasons)

